import { readFileSync, writeFileSync, existsSync } from "node:fs";
const NAME = "{{worker_name}}";
const JOB = "{{job}}";
const MEMORY = "memory.json";
function load() {
  if (!existsSync(MEMORY)) return { ticks: 0 };
  return JSON.parse(readFileSync(MEMORY, "utf8"));
}
function confirm(action) {
  if (process.env.STARTED_CONFIRM === "1") return true;
  console.warn("[gate] denied: " + action);
  return false;
}
function effect(label) {
  if (!confirm(label)) return;
  writeFileSync(MEMORY, JSON.stringify({ ticks: 1, job: JOB }));
}
async function loop() {
  console.log(NAME + " online. job=" + JOB);
  effect("run:" + JOB);
}
loop();
